declare_lint ! { # [doc = " The `invalid_value` lint detects creating a value that is not valid,"] # [doc = " such as a null reference."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " # #![allow(unused)]"] # [doc = " unsafe {"] # [doc = "     let x: &'static i32 = std::mem::zeroed();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In some situations the compiler can detect that the code is creating"] # [doc = " an invalid value, which should be avoided."] # [doc = ""] # [doc = " In particular, this lint will check for improper use of"] # [doc = " [`mem::zeroed`], [`mem::uninitialized`], [`mem::transmute`], and"] # [doc = " [`MaybeUninit::assume_init`] that can cause [undefined behavior]. The"] # [doc = " lint should provide extra information to indicate what the problem is"] # [doc = " and a possible solution."] # [doc = ""] # [doc = " [`mem::zeroed`]: https://doc.rust-lang.org/std/mem/fn.zeroed.html"] # [doc = " [`mem::uninitialized`]: https://doc.rust-lang.org/std/mem/fn.uninitialized.html"] # [doc = " [`mem::transmute`]: https://doc.rust-lang.org/std/mem/fn.transmute.html"] # [doc = " [`MaybeUninit::assume_init`]: https://doc.rust-lang.org/std/mem/union.MaybeUninit.html#method.assume_init"] # [doc = " [undefined behavior]: https://doc.rust-lang.org/reference/behavior-considered-undefined.html"] pub INVALID_VALUE , Warn , "an invalid value is being created (such as a null reference)" }